"""Validation rules migrated from legacy/opportunity_rules.vrl."""

from decimal import Decimal
from typing import Any


def _value(image: dict | None, column: str) -> Any:
    if image is None:
        return ""
    value = image.get(column, "")
    return "" if value is None else value


def _number(value: Any) -> Decimal:
    if value is None or value == "":
        return Decimal(0)
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value))


def _date_gte(left: Any, right: Any) -> bool:
    left_text = "" if left is None else str(left)
    right_text = "" if right is None else str(right)
    if left_text == "00000000" or right_text == "00000000":
        return False
    return left_text >= right_text


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    """Evaluate all applicable opportunity rules in legacy rule-file order."""
    errors: list[dict] = []

    if event not in {"INSERT", "UPDATE"}:
        return errors

    def fail(code: str, message: str, severity: str = "BLOCK") -> None:
        errors.append(
            {
                "code": code,
                "message": message,
                "severity": severity,
            }
        )

    stat_cd = _value(record, "STAT_CD")
    amount = _number(_value(record, "AMT"))
    lost_reason = _value(record, "LOST_RSN")
    close_date = _value(record, "CLOSE_DT")
    stage_pct = _number(_value(record, "STAGE_PCT"))

    # OPP-001
    if not (amount >= Decimal(0)):
        fail("E3001", "Amount negative")

    # OPP-002
    if not not (stat_cd == "W" and amount == Decimal(0)):
        fail("E3002", "Won opportunity requires amount")

    # OPP-003
    if not not (stat_cd == "L" and lost_reason == ""):
        fail("E3003", "Lost reason required")

    # OPP-004
    if not not (stat_cd == "W" and close_date == "00000000"):
        fail("E3004", "Won opportunity requires close date")

    # OPP-005
    if event == "UPDATE":
        old_stat_cd = _value(old, "STAT_CD")
        if not not (old_stat_cd == "W" and stat_cd != "W"):
            fail("E3005", "Cannot reopen a won opportunity")

    # OPP-006
    stage_is_consistent = (
        (stat_cd == "P" and stage_pct == Decimal(10))
        or (stat_cd == "Q" and stage_pct == Decimal(25))
        or (stat_cd == "N" and stage_pct == Decimal(60))
        or (stat_cd == "W" and stage_pct == Decimal(100))
        or (stat_cd == "L" and stage_pct == Decimal(0))
    )
    if not stage_is_consistent:
        fail("E3006", "Stage percent inconsistent with status")

    # OPP-007
    if event == "INSERT":
        close_date_is_valid = (
            close_date == "00000000" or _date_gte(close_date, today)
        )
        if not close_date_is_valid:
            fail("E3007", "Close date in past", "WARN")

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether at least one validation failure blocks the write."""
    return any(error.get("severity") == "BLOCK" for error in errors)
